112	    if (uri != null && uri.contains("jdbc:")) {
113	      logger.info("Setting default connection string to " + uri);
114	      kernelParameters.put(DEFAULT_DATASOURCE, uri);
115	    } else if (uri != null) {
116	      logger.warning("Ignoring incorrectly formatted " + BEAKERX_SQL_DEFAULT_JDBC + ": " + uri);
117	    }
