package com.twosigma.beakerx.sql.magic.command;

import com.twosigma.beakerx.BeakerXClient;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class DataSourceParamResolverImpl implements DataSourceParamResolver {

  private static final Pattern PLACEHOLDER_PATTERN = Pattern.compile("\\{\\$beakerx\\.([^}]+)\\}");

  private final BeakerXClient beakerXClient;

  public DataSourceParamResolverImpl(BeakerXClient beakerXClient) {
    this.beakerXClient = beakerXClient;
  }

  @Override
  public String resolve(String jdbcTemplate) {
    if (jdbcTemplate == null) {
      return null;
    }
    Matcher matcher = PLACEHOLDER_PATTERN.matcher(jdbcTemplate);
    StringBuffer result = new StringBuffer();
    while (matcher.find()) {
      String variableName = matcher.group(1);
      Object value = beakerXClient.get(variableName);
      matcher.appendReplacement(result, Matcher.quoteReplacement(String.valueOf(value)));
    }
    matcher.appendTail(result);
    return result.toString();
  }
}
